      content: `В любой области всегда есть две группы: эксперты и не эксперты. Не эксперты следуют за экспертами. Даже тот, кто в целом представляет тему, всегда будет следовать правилам, установлениям и заключениям экспертов своей области. Обычный терапевт достаточно квалифицирован, чтобы диагностировать большинство заболеваний и прописать лечение. Однако, несмотря на годы учебы и практики, он всегда будет следовать принципам и заключениям медицинских экспертов в своих отраслях.

Всевышний Аллах установил такое же положение дел и в религии. Всевышний Аллах сказал в Коране: «Спрашивайте обладателей знания, если вы не знаете»[1]. И этот фундамент таклида устанавливает Коран.

И мавляна Закария Макада, преподаватель науки хадис в медресе «Та’лимуддин» из Испинго Бич, написал эту работу, чтобы показать важность таклида и опасность отказа от общепризнанных правил исламских наук.

Мавляна Ильяс Пател,
преподаватель науки хадис,
медресе «Та’лимуддин»,
Испинго Бич, ЮАР`,
