      title: 'Обращение к Корану без Сунны Посланника Аллаха (да благословит его Аллах и да приветствует)',
      content: `Среди многих задач пророческой миссии, которые были возложены на Пророка (да благословит его Аллах и да приветствует), было словесное объяснение положений Шариата в Коране и демонстрация на практике.

Всевышний Аллах сказал:

وَأَنْزَلْنَا إِلَيْكَ الذِّكْرَ لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيْهِمْ وَلَعَلَّهُمْ يَتَفَكَّرُونَ

«А тебе Мы ниспослали Наставление (Коран) для того, чтобы ты объяснял людям ниспосланное для них, и для того, чтобы они призадумались (над истиной, содержащейся в Коране)»[5].

Например, в Коране сказано:

وَأَقِيمُوا الصَّلَاةَ

«(Полноценно) совершайте намаз»[6].

Если полностью прочитать Коран, то не найдешь прямых указаний на намазы фаджр, зухр, аср, магриб и иша, и тем более уточнения, сколько в них нужно совершать ракаатов. И не перечислены ваджибы и сунны намаза, а также то, что нарушает намаз и не соответствует его духу.

И любой человек будет вынужден обратиться за всеми этими деталями к Сунне, потому что Сунна фактически — это толкование Корана. И точно такое же положение у поста, закята, хаджа и других положений Шариата.

И из всего этого мы понимаем, что следование хадисам Посланника Аллаха (да благословит его Аллах и да приветствует) — это подчинение Всевышнему Аллаху, на что указал аят:

مَنْ يُطِعِ الرَّسُولَ فَقَدْ أَطَاعَ اللَّهَ

«Кто подчиняется Посланнику, тот подчинился Аллаху»[7].

На это указал и сам Пророк (да благословит его Аллах и да приветствует):

عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: « كُلُّ أُمَّتِي يَدْخُلُونَ الْجَنَّةَ إِلَّا مَنْ أَبَى ». قَالُوا: يَا رَسُولَ اللَّهِ، وَمَنْ يَأْبَى؟ قَالَ: « مَنْ أَطَاعَنِي دَخَلَ الْجَنَّةَ، وَمَنْ عَصَانِي فَقَدْ أَبَى »

От Абу Хурейры [передается], что Посланник Аллаха (да благословит его Аллах и да приветствует) сказал: «Каждый из моей уммы войдет в Рай, кроме отказавшегося». И они спросили: «О Посланник Аллаха, а кто отказавшийся?» И он сказал: «Кто подчинился мне, тот войдет в Рай, а кто ослушался меня, тот отказавшийся»[8].

Этот хадис ясно указывает, что никто не сможет получить спасение без посредничества Посланника Аллаха (да благословит его Аллах и да приветствует).

Более того, никто, даже сподвижники, не могут понимать все аяты Корана без посредничества Сунны Посланника Аллаха (да благословит его Аллах и да приветствует).

Например, есть слова Всевышнего Аллаха:

وَكُلُوا وَاشْرَبُوا حَتَّىٰ يَتَبَيَّنَ لَكُمُ الْخَيْطُ الْأَبْيَضُ مِنَ الْخَيْطِ الْأَسْوَدِ مِنَ الْفَجْرِ

«Ешьте и пейте, пока вы не сможете отличить белую нить от черной на рассвете, а затем продолжайте поститься до ночи»[9].

Ади ибн Хатим ат-Таи (да будет доволен им Аллах) попытался самостоятельно понять этот аят и пришел к ошибочному решению. И он высказал Посланнику Аллаха (да благословит его Аллах и да приветствует) свое понимание, а Посланник Аллаха (да благословит его Аллах и да приветствует) — в свою очередь — исправил его и правильно объяснил этот аят.

Эту историю полностью передает имам Ахмад ибн Ханбаль:

حَدَّثَنَا هُشَيْمٌ ، أَخْبَرَنَا حُصَيْنٌ ، عَنِ الشَّعْبِيِّ ، أَخْبَرَنَا عَدِيُّ بْنُ حَاتِمٍ قَالَ : لَمَّا نَزَلَتْ هَذِهِ الْآيَةُ : { وَكُلُوا وَاشْرَبُوا حَتَّى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الْأَبْيَضُ مِنَ الْخَيْطِ الْأَسْوَدِ } ، قَالَ : عَمَدْتُ إِلَى عِقَالَيْنِ : أَحَدُهُمَا أَسْوَدُ، وَالْآخَرُ أَبْيَضُ، فَجَعَلْتُهُمَا تَحْتَ وِسَادِي، قَالَ : ثُمَّ جَعَلْتُ أَنْظُرُ إِلَيْهِمَا، فَلَا تَبَيَّنَ لِي الْأَسْوَدُ مِنَ الْأَبْيَضِ، وَلَا الْأَبْيَضُ مِنَ الْأَسْوَدِ، فَلَمَّا أَصْبَحْتُ غَدَوْتُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرْتُهُ بِالَّذِي صَنَعْتُ، فَقَالَ : « إِنْ كَانَ وِسَادُكَ إِذَنْ لَعَرِيضًا، إِنَّمَا ذَلِكَ بَيَاضُ النَّهَارِ مِنْ سَوَادِ اللَّيْلِ »

Имам аш-Шааби сказал о том, что Ади ибн Хатим рассказал следующее: «Когда был ниспослан аят: “Ешьте и пейте, пока вы не сможете отличить белую нить от черной на рассвете, а затем продолжайте поститься до ночи”[10], — я взял две нитки: одну черную, а другую белую — и положил их под свою подушку, и потом стал смотреть на них, пока не смог отличить черную от белой и белую от черной. А наутро я пошел к Посланнику Аллаха (да благословит его Аллах и да приветствует) и рассказал ему, что я сделал, и он сказал: “Твоя подушка действительно широка! Речь (в аяте) идет о белизне дня и черноте ночи”[11]».`,
