      title: 'Есть ли доводы в пользу таклида в Коране?',
      content: `Повеление таклида установлено во многих аятах Корана.
Всевышний Аллах сказал:

وَاتَّبِعْ سَبِيلَ مَنْ أَنَابَ إِلَيَّ

«Иди путем тех, кто обратился ко Мне (с поклонением, подчинившись Моим повелениям)»[17].

И Всевышний Аллах сказал:

فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لَا تَعْلَمُونَ

«Спросите у людей знающих, если сами не знаете»[18].

Также Всевышний Аллах сказал:

يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُولِي الْأَمْرِ مِنْكُمْ

«О верующие! Подчиняйтесь Аллаху, подчиняйтесь Посланнику и вашим руководителям»[19].

Такие толкователи Корана, как аль-Джассас, ар-Рази и аль-Алюси указали, что под «руководителями» также подразумеваются ученые и факихи этой уммы, и поэтому сама концепция таклида установлена этим аятом.

Навваб Сыдык Хан, известный ученый безмазхабников, в своей книге «Аль-Джунна» подтверждает это толкование словами: «Ибн Аббас, Джабир, аль-Хасан, Абу аль-Алия, Ата, ад-Даххак, Муджахид и имам Ахмад сказали, что это ученые (подразумеваются в аяте под «вашими руководителями»)»[20].

Затем Навваб Сыдык Хан сказал: «Правильное мнение тут — что подчиняться правителям обязательно, когда они повелевают на основе знания, и поэтому следование за ними подразумевает следование за учеными, подобно тому, как следование за учеными — это следование за Посланником Аллаха (да благословит его Аллах и да приветствует)»[21].`,
