      title: 'Есть ли доводы в пользу таклида в Сунне?',
      content: `Повеление таклида установлено во многих хадисах. И мы приведем лишь некоторые из этих многочисленных хадисов.

В благословенную эпоху Посланника Аллаха (да благословит его Аллах и да приветствует) Му’аз ибн Джабаль (да будет доволен им Аллах) был назначен Посланником Аллаха (да благословит его Аллах и да приветствует) наместником Йемена.

И Посланник Аллаха (да благословит его Аллах и да приветствует) велел жителям Йемена задавать вопросы о религии Му’азу (да будет доволен им Аллах), и это означает, что начало таклида было положено еще во времена Посланника Аллаха (да благословит его Аллах и да приветствует) с прямого его разрешения.

عَنِ الْأَسْوَدِ بْنِ يَزِيدَ، قَالَ: أَتَانَا مُعَاذُ بْنُ جَبَلٍ بِالْيَمَنِ مُعَلِّمًا وَأَمِيرًا، فَسَأَلْنَاهُ عَنْ رَجُلٍ تُوُفِّيَ وَتَرَكَ ابْنَتَهُ وَأُخْتَهُ، فَأَعْطَى الِابْنَةَ النِّصْفَ، وَالْأُخْتَ النِّصْفَ.

От аль-Асвада ибн Язида [передается]: «Му’аз ибн Джабаль прибыл к нам в Йемен и как учитель, и как правитель. И мы спросили его о (разделе наследства) человека, который умер и оставил после себя дочь и сестру, и он установил дочери половину и сестре половину»[22].

، عَنْ حُذَيْفَةَ رَضِيَ اللَّهُ عَنْهُ، قَالَ : كُنَّا جُلُوسًا عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ : « إِنِّي لَا أَدْرِي مَا بَقَائِي فِيكُمْ، فَاقْتَدُوا بِاللَّذَيْنِ مِنْ بَعْدِي ». وَأَشَارَ إِلَى أَبِي بَكْرٍ، وَعُمَرَ

От Хузейфы (да будет доволен им Аллах) [передается]: «Мы сидели рядом с Пророком (да благословит его Аллах и да приветствует), и он сказал: «Я не знаю, сколько еще мне осталось быть среди вас. Следуйте за этими двумя после меня», — и он указал на Абу Бакра и Умара»[23].

Из первого хадиса мы понимаем, что Посланник Аллаха (да благословит его Аллах и да приветствует) не повелевал жителям Йемена напрямую обращаться к Сунне, но им было велено со своими шариатскими вопросами обращаться к Му’азу (да будет доволен им Аллах). Посланник Аллаха (да благословит его Аллах и да приветствует) велел жителям Йемена — а в их лице и всей умме — совершать таклид, потому что каждый человек не способен самостоятельно выносить решения из Корана и Сунны. Прямое обращение к Корану и Сунне для вынесения шариатских установлений — это обязанность лишь крайне квалифицированных ученых, известных как имамы иджтихада.

Второй же хадис повелевает нам следовать по пути Абу Бакра и Умара (да будет Аллах доволен ими обоими). И Посланник Аллаха (да благословит его Аллах и да приветствует) не просил нас ставить под сомнение их доказательства, потому что они обладали всеми необходимыми знаниями для вынесения шариатских решений из Корана и Сунны, но Посланник Аллаха (да благословит его Аллах и да приветствует) сказал нам лишь следовать за ними, а это и есть таклид.

وَحَدَّثَنِي عَنْ مَالِكٍ، عَنْ عُثْمَانَ بْنِ حَفْصِ بْنِ خَلْدَةَ، عَنِ ابْنِ شِهَابٍ ، عَنْ سَالِمِ بْنِ عَبْدِ اللَّهِ ، عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ أَنَّهُ سُئِلَ عَنِ الرَّجُلِ يَكُونُ لَهُ الدَّيْنُ عَلَى الرَّجُلِ إِلَى أَجَلٍ، فَيَضَعُ عَنْهُ صَاحِبُ الْحَقِّ وَيُعَجِّلُهُ الْآخَرُ ؟ فَكَرِهَ ذَلِكَ عَبْدُ اللَّهِ بْنُ عُمَرَ وَنَهَى عَنْهُ

Салим сообщает от Абдуллаха ибн Умара, что его спросили о человеке, который был должником, и он хотел раньше вернуть долг, но с условием, чтобы ему за это простили часть суммы. И Абдуллах ибн Умар запретил это[24].

Мавляна Ашраф Али Танви (да помилует его Аллах) подметил, что это решение Абдуллах ибн Умара (да будет доволен им Аллах) вынес, не предоставляя никакого довода. А задавший вопрос не спросил, на основе какого довода Абдуллах ибн Умар (да будет доволен им Аллах) вынес свое решение. Но он доверял решению сподвижника, зная, какое положение тот занимал, и что он мог выносить решения напрямую из Корана и Сунны.

И на основе всего этого мы понимаем, что таклид существовал уже при жизни Посланника Аллаха (да благословит его Аллах и да приветствует).`,
