      id: 714,
      bookId: 7,
      chapterOrder: 14,
      title: 'Обращение к экспертам',
      content: `В мирских делах распространен принцип: «Нужно обращаться к специалисту в своей области». Например, если человек захочет построить трехэтажный дом, то сначала он обратится к архитектору за планом, затем — к инженерам по строительству, чтобы получить их консультации, и к подрядчикам, чтобы узнать о ходе строительства. Если мы предположим, что этот человек захочет построить дом сам, не обращаясь к архитекторам, инженерам и подрядчикам, то несложно представить, какой плачевный итог будет у его затеи.

Точно так же, если человек страдает от острых болей или тяжелой болезни, такой как рак или сердечная недостаточность, и врач ему сказал, что ему срочно нужно сделать операцию, а иначе девяносто девять процентов вероятности из ста процентов, что он умрет, то если человек в таком опасном положении начнет сам читать медицинские журналы, а потом осмелится сам провести на себе операцию, как мы отреагируем?

Эти принципы мы можем наблюдать во всех аспектах жизни. Люди обращаются к тем, кого они считают экспертами в интересующих их областях, чтобы получить наставление и помощь. По сути, это и есть таклид — «опираться на суждение эксперта».

Если мы рассмотрим различные области исламских наук, то, без сомнения, поймем, что без опоры и доверия к специалистам невозможно прогрессировать в этих науках.

С самого начала, с мактаба[31], от ребенка требуют, чтобы он был уверен в своем учителе или учительнице, чтобы таким образом они смогли научиться читать Коран. Уже на втором уровне ребенок начинает заучивать Коран и совершенствовать свое чтение. И на этом уровне он должен доверять учителю и его знаниям. Затем ребенок поступает в медресе, продолжая научно развиваться. Он посещает различные уроки, которые ведут квалифицированные учителя. И на этом уровне он подстраивает свое понимание под понимание своих учителей, которых он считает специалистами в своем деле. И после окончания определенного периода учебы он получает сертификат о своей компетентности в различных шариатских областях.

Мы видим, что научное развитие, как в мирском, так и в религиозном, с точки зрения Шариата связано с таклидом.

Всевышний Аллах сказал:

فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لَا تَعْلَمُونَ

«Спросите у людей знающих, если сами не знаете»[32].

Проблема же наших дней в том, что человека считают экспертом в религии, если его знания чуть больше знаний обычного человека. Такому сразу же начинают задавать вопросы об Исламе. Но если сравнить современных экспертов религии с экспертами прошлого, то современные специалисты были бы ниже уровнем, чем обычные люди той эпохи.

И все это приводит нас к заключению, что если мы захотим следовать наставлению того, кто вобрал знания всех аспектов религии: Корана, Сунны, истории, решений сподвижников и так далее, — то в наши дни невозможно найти никого, кроме четыре имамов, чье наследие было сохранено на протяжении всей истории Ислама в отличие от наследия других имамов иджтихада.`,
