      content: `Многие ученые прошлого ясно сказали, что таклид ограничен только следованием одному из четырех мазхабов.

Об этом имам Абдур-Рахман ибн Мухаммад аль-Магриби говорит следующее: «Таклид ограничен на всех землях мусульман только следованием этим четырем имамам. Следующих за другими имамами больше не осталось. И когда научная терминология распространилась, то ученые закрыли двери разногласий, ограничив таклид одним из этих четырех имамов, потому что они боялись, что не обладающий достаточными знаниями будет претендовать на иджтихад. И поэтому ученые сказали: «Достижение степени иджтихада практически невозможно». А людей они направили к следованию за одним из четырех имамов, предостерегая их от смены мазхаба для облегчения, чтобы они не превращали религию Аллаха в игру. И поэтому любые заявления об иджтихаде в эту эпоху будут отвергнуты, и за этим человеком нельзя будет следовать. Весь мусульманский мир сошелся на том, что можно следовать [в фикхе] только за одним из четырех имамов»[33].`,
