      content: `Изучающий жизнь четырех имамов — имама Абу Ханифы, имама Малика, имама Шафии и имама Ахмада, — будет убежден, что они получили статус имамов-муджтахидов заслуженно. Их богобоязненность, набожность и постоянство в следовании каждому аспекту учения Корана и Сунны вместе с их энциклопедическими знаниями всех аспектов шариатских наук сделало их центром притяжения для своего времени и проводником по истинному пути вплоть до наших дней. Их можно считать сосредоточием знания поколения сподвижников и табиинов. И Всевышний Аллах выбрал из миллиона ученых именно их для наставления уммы мусульман в течение веков — вплоть до наших дней.`,
