      id: 720,
      bookId: 7,
      chapterOrder: 20,
      title: 'Имам Ахмад ибн Ханбаль (да помилует его Аллах)',
      content: `Имам Ахмад ибн Ханбаль родился в 164-м году по хиджре, а скончался утром в пятницу 12-го рабиуль-авваля 241-го года в возрасте семидесяти семи лет[104].

Знания имама

Имам Ибрахим аль-Харби (умер в 285-м году) сказал: «У меня была возможность увидеть Ахмада ибн Ханбаля. Его сердце казалось сокровищницей, в которой собраны знания всех людей. И он показывал то, что считал нужным, а что не считал нужным показывать, то не упоминал».

Абу Зур’а сказал: «Ахмад ибн Ханбаль знал наизусть миллион хадисов. Я повторял с ним хадисы, обсуждая различные их разделы».

Имам Абдур-Раззак сказал: «Я не видел никого сильнее в фикхе и набожности, чем Ахмад ибн Ханбаль»[105].

Хармаля передает, что слышал, как имам аш-Шафии сказал: «Когда я покидал Багдад, то самым знающим в фикхе из тех, кто там остался, был Ахмад ибн Ханбаль»[106].

Али ибн аль-Мадини сказал: «Всевышний Аллах поддержал эту умму двумя выдающимися людьми: Абу Бакром, когда арабские племена стали вероотступниками, и Ахмадом ибн Ханбалем, когда умма была испытана темой сотворенности Корана»[107].

Нрав имама

Мухаммад ибн Хасан ибн Харун сказал: «Я видел, как Абу Абдуллах (Ахмад ибн Ханбаль) шел по улице, и ему не нравилось, когда кто-то шел за ним»[108].

Имам Яхья ибн Маин сказал: «Я не видел никого подобного Ахмаду ибн Ханбалю. Я знал его в течение пятидесяти лет, и он никогда свои благие дела не выставлял напоказ»[109].

Испытания имама

Имам Ахмад ибн Ханбаль прошел через сложнейшие испытания и пытки по велению правителей своего времени. В рамадан в 221-м году, когда ему было пятьдесят семь лет, имама арестовали и избили плетьми по повелению халифа аль-Мутасыма. И это случилось только из-за воззрений имама в области акыды, где заблудшие сектанты отклонились (то есть касательно сотворенности Корана). Его ударили семнадцать раз, и он почти потерял сознание. После пыток его бросили лицом вниз, а спину накрыли тканью. Когда он пришел в себя и ему принесли пищу, то он отказался есть, потому что постился. Он простил всех, кто участвовал в его избиении, кроме заблудших. И он говорил: «Какая тебе будет польза, если из-за тебя будет наказан твой брат-мусульманин?»

Потом Всевышний Аллах наставил аль-Мутасыма, который покаялся в содеянном и выказывал огромное уважение имаму Ахмаду.

После испытаний

После аль-Васика халифом стал аль-Мутаваккиль в 232-м году. Этот правитель был очень хорошего мнения об имаме Ахмаде ибн Ханбале, но имам избегал его, полагая, что близость к правителям приводит к бедам.

Однажды аль-Мутаваккиль направил имаму мешок с десятью тысячами дирхамов и двумястами динарами. И ему сказали, что он обязан принять это, иначе халиф оскорбится. Имам Ахмад ибн Ханбаль даже не посмотрел на эти деньги. И, когда было время намаза магриб, имам позвал своего сына Салиха и сказал ему: «Возьми это себе».

Наутро имам позвал своего сына Салиха, который тут же пришел, и сказал ему: «Я не мог спать всю ночь», — и он заплакал. Затем он сказал: «Всю свою жизнь я был защищен от правителей. Теперь в старости меня испытывают ими. И я решил раздать эти деньги утром». И в это утро имам раздал все это имущество нуждающимся и даже отдал сам мешок нуждающемуся. И его сын сказал: «Лишь Аллах знает, в какой нужде мы тогда жили»[110].

Набожность имама

Сын имама, Абдуллах, сообщает: «Мой отец каждый день совершал триста ракаатов. Когда он ослаб из-за ударов плетьми, то совершал каждый день по сто пятьдесят ракаатов. И тогда он был близок к восьмидесяти годам. Он каждый день читал одну седьмую часть Корана, делая хатм каждую неделю. После намаза иша он немного спал, а затем вставал для намаза и дуа. Мой отец совершил хадж пять раз, из которых три были пешими, а два — верхом. И в одном из хаджей он потратил только двадцать дирхамов»[111].

Ибрахим ибн Шаммас сказал: «Я знаю, что имам Ахмад ибн Ханбаль, еще будучи ребенком, уже не спал по ночам (совершая поклонение)»[112].

Адаб имама

Имам Ахмад ибн Ханбаль никогда не называл учителей по именам в знак уважения к ним. Он обращался к ним по их титулам[113].

Однажды имам болел и не вставал. И в середине какого-то обсуждения кто-то упомянул имя Ибрахима ибн Тахмана. Когда имам услышал его имя, то сразу же встал в знак уважения и потом сказал: «Не следует произносить имена праведников лежа»[114].`,
