        'Методы обучения в благословенную эпоху Пророка (да благословит его Аллах и да приветствует)',
      content: `В эпоху сподвижников (да будет доволен Аллах ими всеми) методом обучения было изучение Корана и Сунны под наставничеством ученого, который был знатоком разных аспектов религии. Сами же сподвижники, несмотря на идеальное знание арабского языка, никогда в области религии не опирались на личные знания и не обращались напрямую к Корану и Сунне, потому что они знали о предостережении Посланника Аллаха (да благословит его Аллах и да приветствует) в отношении такого подхода и его плачевных последствиях.

В одном из хадисов сказано:

«Кто выдумает что-то в религии и ложно отнесет это ко мне, тот пусть готовит себе место в Аду»[198].

Обычно люди, самостоятельно изучающие Коран и Сунну, приходят к ошибочным выводам и ложному пониманию. В результате они начинают доводить этот ложный посыл до уммы, относя это суждение ко Всевышнему Аллаху и Его Посланнику (да благословит его Аллах и да приветствует). И существуют серьезные опасения, что к таким людям может относиться этот хадис.

Более того, Посланник Аллаха (да благословит его Аллах и да приветствует) предсказал появление подобных людей ближе к Судному дню, когда истинный дух Ислама, который был в начале, начнет исчезать. И осторожность в вопросах религии, которая была повсеместной во время сподвижников, перестанет существовать, а люди начнут напрямую обращаться к Корану и Сунне для вынесения решений.

وروي عن أبي مالك الأشعري أنه سمع النبي صلى الله عليه وسلم يقول لا أخاف على أمتي إلا ثلاث خلال أن يكثر لهم من الدنيا فيتحاسدوا وأن يفتح لهم الكتاب يأخذه المؤمن يبتغي تأويله وما يعلم تأويله إلا الله والراسخون في العلم يقولون آمنا به كل من عند ربنا وما يذكر إلا أولو الألباب وأن يروا ذا علم فيضيعوه ولا يبالوا عليه

Передается, что Пророк (да благословит его Аллах и да приветствует) сказал: «Я боюсь для своей общины трех вещей: умножения мирских благ, так что они начнут завидовать друг другу. И (еще я боюсь, что они) начнут открыто рассуждать о Коране и толковании тех аятов, толкование которых знает только Всевышний Аллах, а истинные знатоки (Писания) будут говорить: «Мы уверовали во все от нашего Господа». (И третье —) что учеными будут пренебрегать, не обращая на них внимания (то есть люди будут самостоятельно изучать Коран и Сунну)»[199].`,
