      id: 724,
      bookId: 7,
      chapterOrder: 24,
      title: 'Вред от обращения обычного человека к Корану и Сунне',
      content: `Один человек как-то пришел к Умару (да будет доволен им Аллах) для определенных работ. И Умар (да будет доволен им Аллах) спросил его о положении людей в его местности.

И этот человек сказал: «О повелитель правоверных, среди людей серьезное оживление: люди изучают Коран и обращаются к нему напрямую в своих делах (то есть не обращаясь к ученым)».

И при этом общении присутствовал Ибн Аббас (да будет доволен Аллах ими обоими), и когда он услышал эти слова, то сказал: «Клянусь Аллахом, мне не нравится, что люди самостоятельно изучают Коран».

И как только Умар (да будет доволен им Аллах) услышал эти слова, то сразу же сделал выговор ему и не согласился с его критикой. И после выговора от Умара (да будет доволен им Аллах) Абдуллах ибн Аббас (да будет доволен Аллах ими обоими) сказал: «Я пошел домой сильно опечаленным и сказал самому себе: «Кажется из-за моих слов я упал в глазах Умара (да будет доволен им Аллах) и потерял свое положение». Я направился домой и прилег, и женщины дома начали беспокоиться обо мне. И это было не из-за того, что я заболел, но из-за того разговора с Умаром (да будет доволен им Аллах). И когда я находился в таком состоянии, то пришел человек и сказал: «Повелитель правоверных послал за тобой». И когда я вышел из дома, то увидел, что Умар (да будет доволен им Аллах) ждет меня.

И он взял меня за руку, а когда мы оказались одни, то спросил: «Что именно тебе не понравилось в словах того человека?»

И я ответил: «О повелитель правоверных, если я ошибся, то я прошу у Аллаха простить меня и готов изменить свое мнение, как ты скажешь».

Умар (да будет доволен им Аллах) сказал: «Нет, лучше скажи мне, почему ты так считаешь».

Тогда я ответил: «Повелитель правоверных, мне не нравится, что люди прямо обращаются к Корану, потому что они начнут приходить к своим решениям и высказывать собственное суждение о религии. И в итоге у каждого человека будет своя версия религии, и он будет сводить истину только к тому, что ему лично кажется верным. И это приведет к разногласиям и разделению рядов мусульман (из-за невежества). Это разделение приведет к спорам, которые приведут к сражению мусульман против мусульман».

Умар (да будет доволен им Аллах) был доволен тем, что услышал от Ибн Аббаса (да будет доволен ими обоими Аллах), и сказал ему, что сам так же считает, и он никому об этом не говорил до того, как Ибн Аббас сказал ему это[200].`,
