      id: 725,
      bookId: 7,
      chapterOrder: 25,
      title: 'Салафизм под микроскопом',
      content: `Салафизм — это новый мировой тренд, который, хоть и имеет религиозную форму, лишен духа религии. Спустя двенадцать веков, на протяжении которых умма следовала четырем мазхабам, объявился этот новый мазхаб.

Большинство людей, которые себя относят к этому мазхабу, хотят вести свободный и беззаботный образ жизни. Они не хотят никаких ограничений в мирском, но при этом хотят производить впечатление религиозных людей, которые практикуют религиозные установления. И поэтому они крайне озабочены тем, чтобы люди не отделяли их от остальной уммы, называя их нарушителями устоев религии из-за их небрежности в религии.

Претендуя на то, что они якобы напрямую следуют хадисам, они пытаются создать впечатление, что только они следуют за Посланником Аллаха (да благословит его Аллах и да приветствует), а последователи мазхабов следуют за своими имамами, но не за Посланником Аллаха (да благословит его Аллах и да приветствует). Но они не понимают, что каждый имам направлял только в сторону следования за Кораном и Сунной в первозданном виде. На самом деле именно салафиты и те, кто разделяет их идею отойти от мейнстрима уммы, противостоят Сунне во многих аспектах религии.

Они выбрали ряд мнений из разных мазхабов, выделяя источники этих решений из известных книг хадисов, таких как сборники Бухари и Муслима. И этим они создали впечатление в умме, что только их путь верен, а все остальные ошибаются. И с таким подходом они стали игнорировать в этих темах другие достоверные хадисы, на которые опирались другие мазхабы.

И в ситуации, когда все четыре имама не практиковали определенный хадис на основе своих сильных доводов, салафиты брали эти хадисы в практику, критикуя имамов за отказ следовать хадисам.

Мы заметили, что когда в одной из тем существуют разногласия между имамами, то они поощряют людей исследовать тему самостоятельно и выбирать то мнение, которое будет казаться более верным.`,
