      title: 'Суть салафизма',
      content: `Салафизм — это набор мнений из разных мазхабов с добавлением некоторых личных суждений. И они считают, что когда человек сталкивается со сложностями, то можно тут же взять мнение другого имама, выбирая мнения, которые ближе человеку. И если попытаться как-то облагоразумить такого человека, то он в свое оправдание приводит следующий хадис:

عن أبي هريرة قال قال رسول الله صلى الله عليه وسلم إذا حكم الحاكم فاجتهد فأصاب فله أجران وإذا حكم فأخطأ فله أجر واحد

От Абу Хурейры: «Посланник Аллаха (да благословит его Аллах и да приветствует) сказал: “Если судья вынес решение и оказался прав, то ему две награды, а если ошибся, то одна”»[207].

Но, ссылаясь на этот хадис, они не поняли, что в нем речь идет о муджтахиде, который обладает всеми навыками для иджтихада, каковыми были четыре имама и другие муджтахиды из числа сподвижников и табиинов.

В этом хадисе не идет речь про обычного человека, хадисы о котором они как раз игнорируют. Существует множество хадисов, которые запрещают простолюдинам вмешиваться в решения Шариата. Ясный довод на это изложен в следующем хадисе:

عن جابر قال خرجنا في سفر فأصاب رجلا منا حجر فشجه في رأسه فاحتلم فسأل أصحابه هل تجدون لي رخصة في التيمم قالوا ما نجد لك رخصة و أنت تقدر على الماء فاغتسل فمات فلما قدمنا على النبي صلى الله عليه وسلم أُخبر بذلك قال قتلوه قتلهم الله ألا سألوا إذا لم يعلموا فإنما شفاء العي السؤال إنما كان يكفيه أن يتيمم و يعصب على جرحه خرقة ثم يمسح عليها و يغسل سائر جسد

От Джабира: «Мы были в пути, когда один человек разбил себе голову об скалу, и когда у него случилась поллюция, то он спросил окружающих: “Есть ли мне облегчение для таяммума?”

И они сказали: “Мы не видим для тебя облегчения, потому что ты можешь использовать воду”.

И он совершил полное купание, а потом умер. И когда мы прибыли, то об этом сообщили Пророку (да благословит его Аллах и да приветствует) и он сказал: “Они убили его! Да погубит их Аллах! Разве не могли они спросить, если не знали?! Вопрос — лекарство от незнания! Ему было достаточно совершить таяммум, а рану перевязать, а затем протирать ее и мыть остальное тело!”»[208]

Из этого хадиса мы понимаем, что простолюдинам запрещается самостоятельно совершать иджтихад, пытаясь самостоятельно прийти к решению в области религии. А иначе Посланник Аллаха (да благословит его Аллах и да приветствует) спросил бы их: «Вы совершили иджтихад, прежде чем вынести решение?»

И именно потому, что обычным людям запрещено самостоятельно выносить решения из Корана и Сунны, Посланник Аллаха (да благословит его Аллах и да приветствует) так сильно разгневался на них.`,
